SELECT b.NUM, IFNULL(a.SNOW, -99999) AS SNOW 
	FROM ( SELECT SNOW, DATE_FORMAT(SNOW_DATE, #{format}) AS NUM
			FROM SNOW_HIST
			WHERE DATA_TYPE = #{type} AND AREA_CODE = #{area_code} 
			AND SNOW_DATE IN (${where_date}) ) AS a
	RIGHT JOIN ( SELECT NUM 
				FROM STATISTICS_TMP
				WHERE TYPE = #{type}

		 AND NUM <=  #{ecnt}

	) AS b ON a.NUM = b.NUM 
	ORDER BY b.NUM


		SELECT COUNT(*) AS cnt
		FROM SNOW_HIST
		WHERE AREA_CODE = #{area_code} AND DATA_TYPE = #{type} 
 		AND SNOW_DATE = #{where_date}

